def choose_move(observation):
    # Minimal, deterministic mover: move toward nearest resource if any, else stay or move toward opponent.
    pos = observation.get("self_position", observation.get("position", {"x":0,"y":0}))
    opp = observation.get("opponent_position", {"x":0,"y":0})
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    try:
        x = int(pos.get("x", 0))
        y = int(pos.get("y", 0))
    except Exception:
        x, y = 0, 0

    try:
        ox = int(opp.get("x", 0))
        oy = int(opp.get("y", 0))
    except Exception:
        ox, oy = 0, 0

    resources = observation.get("resources", [])
    if not isinstance(resources, list):
        resources = []

    # Clamp helper
    def clamp(v, lo, hi):
        if v < lo:
            return lo
        if v > hi:
            return hi
        return v

    best = None
    best_score = -10

    # Heuristic: prefer moving towards nearest resource, else toward opponent, else stay
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx = clamp(x + dx, 0, max(grid_w-1, 0))
            ny = clamp(y + dy, 0, max(grid_h-1, 0))
            score = 0
            # resource proximity
            for r in resources:
                rx = int(r.get("x", 0))
                ry = int(r.get("y", 0))
                dist = abs(rx - nx) + abs(ry - ny)
                if dist == 0:
                    score += 5
                else:
                    score -= dist
            # towards opponent
            dist_opp = abs(ox - nx) + abs(oy - ny)
            score -= dist_opp * 0  # neutral to keep deterministic
            if score > best_score:
                best_score = score
                best = (dx, dy)

    if best is None:
        best = (0, 0)

    return [int(best[0]), int(best[1])]
